import{_ as s,o as c,a as t,b as e}from"./app.UgfkfLuP.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API<a npu_parse_enabled=\\"true\\"></a>","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"数据搬运导览","link":"/api/SIMD-API/c_api/data_move_guide/data_move_guide"},{"text":"L1与L0数据搬运","link":"/api/SIMD-API/c_api/data_move_guide/l1_l0_data_move"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/data_move_guide/l1_l0_data_move.md","filePath":"api/SIMD-API/c_api/data_move_guide/l1_l0_data_move.md","outlineHeaders":[{"level":2,"title":"总体说明","slug":"总体说明","link":"#总体说明"},{"level":2,"title":"L1到L0A二维分形矩阵搬运","slug":"L1到L0A二维分形矩阵搬运","link":"#L1到L0A二维分形矩阵搬运"},{"level":2,"title":"L1到L0B二维分形矩阵搬运","slug":"L1到L0B二维分形矩阵搬运","link":"#L1到L0B二维分形矩阵搬运"},{"level":2,"title":"L1到L0A三维img2col搬运","slug":"L1到L0A三维img2col搬运","link":"#L1到L0A三维img2col搬运"},{"level":2,"title":"L1到L0B三维img2col搬运","slug":"L1到L0B三维img2col搬运","link":"#L1到L0B三维img2col搬运"},{"level":2,"title":"L1到L0B二维分形转置搬运","slug":"L1到L0B二维分形转置搬运","link":"#L1到L0B二维分形转置搬运"},{"level":2,"title":"MX量化系数搬运","slug":"MX量化系数搬运","link":"#MX量化系数搬运"},{"level":2,"title":"asc_copy_l0c2l1（L0C到L1随路处理搬运）","slug":"asc_copy_l0c2l1（L0C到L1随路处理搬运）","link":"#asc_copy_l0c2l1（L0C到L1随路处理搬运）"},{"level":2,"title":"同步与边界检查","slug":"同步与边界检查","link":"#同步与边界检查"}],"lastUpdated":1791622466000}'),_={name:"api/SIMD-API/c_api/data_move_guide/l1_l0_data_move.md"};function l(p,a,n,d,o,i){return c(),t("div",null,[...a[0]||(a[0]=[e(`<div><article class="markdown-body"><h1>L1与L0数据搬运</h1><p>L1到L0A/L0B用于为Cube矩阵计算装载左、右矩阵，由PIPE_MTE1执行；矩阵计算结果位于L0C，可由PIPE_FIX搬到L1。NPU架构版本3510的通路具有方向性，不提供L0A/L0B到L1或L1到L0C的通用复制。</p><h2 id="总体说明">总体说明<a class="header-anchor" href="#总体说明">​</a></h2><table><thead><tr><th>方向</th><th>搬运模式</th><th>接口</th></tr></thead><tbody><tr><td>L1到L0A</td><td>二维分形搬运</td><td><a href="../cube_datamove/cube_compute_load/asc_copy_l12l0a_2d_arch_3510.html">asc_copy_l12l0a</a></td></tr><tr><td>L1到L0A</td><td>二维分形伴转置搬运</td><td><a href="../cube_datamove/cube_compute_load/asc_copy_l12l0a_2d_arch_3510.html">asc_copy_l12l0a_transpose</a></td></tr><tr><td>L1到L0A</td><td>三维img2col搬运</td><td><a href="../cube_datamove/cube_compute_load/asc_copy_l12l0a_3d_arch_3510.html">asc_copy_l12l0a</a></td></tr><tr><td>L1到L0A_MX</td><td>MX左矩阵量化系数搬运</td><td><a href="../cube_datamove/cube_compute_load/asc_copy_l12l0a_mx.html">asc_copy_l12l0a_mx</a></td></tr><tr><td>L1到L0B</td><td>二维分形搬运</td><td><a href="../cube_datamove/cube_compute_load/asc_copy_l12l0b_2d_arch_3510.html">asc_copy_l12l0b</a></td></tr><tr><td>L1到L0B</td><td>二维分形伴转置搬运</td><td><a href="../cube_datamove/cube_compute_load/asc_copy_l12l0b_2d_arch_3510.html">asc_copy_l12l0b_transpose</a></td></tr><tr><td>L1到L0B</td><td>三维img2col搬运</td><td><a href="../cube_datamove/cube_compute_load/asc_copy_l12l0b_3d_arch_3510.html">asc_copy_l12l0b</a></td></tr><tr><td>L1到L0B</td><td>按Repeat和分形间隔执行二维分形转置</td><td><a href="../cube_datamove/cube_compute_load/asc_copy_l12l0b_trans_arch_3510.html">asc_copy_l12l0b_trans</a></td></tr><tr><td>L1到L0B_MX</td><td>MX右矩阵量化系数搬运</td><td><a href="../cube_datamove/cube_compute_load/asc_copy_l12l0b_mx.html">asc_copy_l12l0b_mx</a></td></tr><tr><td>L0C到L1</td><td>搬出矩阵结果，可组合量化、激活和格式转换</td><td><a href="../cube_datamove/cube_compute_store/asc_copy_l0c2l1_arch_3510.html">asc_copy_l0c2l1</a></td></tr></tbody></table><h2 id="L1到L0A二维分形矩阵搬运">L1到L0A二维分形矩阵搬运<a class="header-anchor" href="#L1到L0A二维分形矩阵搬运">​</a></h2><p><a href="../cube_datamove/cube_compute_load/asc_copy_l12l0a_2d_arch_3510.html">asc_copy_l12l0a</a>按源矩阵行列起始位置、搬运分形数和源/目的分形步长，把L1中的二维矩阵装载到L0A。<code>asc_copy_l12l0a_transpose</code>使用相同参数形式，在搬运时对分形矩阵执行转置。</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_l12l0a</span><span class="p">(</span><span class="n">__ca__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                       </span><span class="n">__cbuf__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                       </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">m_start_position</span><span class="p">,</span>
<span class="w">                                       </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">k_start_position</span><span class="p">,</span>
<span class="w">                                       </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">m_step</span><span class="p">,</span>
<span class="w">                                       </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">k_step</span><span class="p">,</span>
<span class="w">                                       </span><span class="kt">int16_t</span><span class="w"> </span><span class="n">src_stride</span><span class="p">,</span>
<span class="w">                                       </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">dst_stride</span><span class="p">)</span>
</code></pre></div><ul><li><code>src</code>需要32字节对齐，<code>dst</code>需要512字节对齐。</li><li><code>m_start_position</code>和<code>m_step</code>以16个元素为单位；<code>k_start_position</code>以32字节为单位。</li><li><code>src_stride</code>和<code>dst_stride</code>均以512字节分形为单位。</li><li>不同数据位宽的L0A分形形状不同：b4为16×64，b8为16×32，b16为16×16，b32为16×8；每个分形均占512字节。</li><li><code>m_step</code>或<code>k_step</code>为0时不执行搬运。转置模式还需满足不同数据位宽对应的步长倍数约束。</li></ul><h2 id="L1到L0B二维分形矩阵搬运">L1到L0B二维分形矩阵搬运<a class="header-anchor" href="#L1到L0B二维分形矩阵搬运">​</a></h2><p><a href="../cube_datamove/cube_compute_load/asc_copy_l12l0b_2d_arch_3510.html">asc_copy_l12l0b</a>和<code>asc_copy_l12l0b_transpose</code>的参数语义与L0A二维搬运一致，但目的为L0B。不同数据位宽的L0B分形形状为：b4的64×16、b8的32×16、b16的16×16和b32的8×16。</p><p>二维搬运最小粒度为一个512字节完整分形。矩阵边界不足一个分形时，需要在L1中准备完整分形并按矩阵计算要求填充无效元素。L0B目的范围不得超过64KB。</p><h2 id="L1到L0A三维img2col搬运">L1到L0A三维img2col搬运<a class="header-anchor" href="#L1到L0A三维img2col搬运">​</a></h2><p>L0A三维模式将L1中的NC1HWC0 Feature Map执行Image to Column展开，并按目的矩阵起点和范围选取分形写入L0A。主要参数包括：</p><ul><li><code>k_extension</code>、<code>m_extension</code>：目的矩阵width、height方向的传输长度。</li><li><code>k_start_pt</code>、<code>m_start_pt</code>：目的矩阵width、height方向的起点。</li><li><code>stride_w</code>、<code>stride_h</code>：卷积核滑动步长。</li><li><code>filter_w</code>、<code>filter_h</code>和膨胀系数：描述卷积窗口。</li><li><code>channel_size</code>：源Feature Map通道数。</li></ul><p>调用主接口前需要完成以下配置：</p><table><thead><tr><th>配置内容</th><th>接口</th></tr></thead><tbody><tr><td>Feature Map宽、高及四周Padding</td><td><a href="../cube_datamove/cube_load_aux_config/asc_set_l13d_fmatrix.html">asc_set_l13d_fmatrix</a></td></tr><tr><td>Padding值与填充模式</td><td><a href="../cube_datamove/cube_load_aux_config/asc_set_l12l0a_3d_padding.html">asc_set_l12l0a_3d_padding</a></td></tr><tr><td>目的步长、Repeat方向、次数和步长</td><td><a href="../cube_datamove/cube_load_aux_config/asc_set_l13d_rpt.html">asc_set_l13d_rpt</a></td></tr></tbody></table><p><code>stride_w</code>和<code>stride_h</code>的有效范围为[1, 63]。传输长度、卷积核尺寸或通道数使接口成为空操作的条件，以及各数据位宽的通道余数约束，请以接口文档为准。</p><h2 id="L1到L0B三维img2col搬运">L1到L0B三维img2col搬运<a class="header-anchor" href="#L1到L0B三维img2col搬运">​</a></h2><p>L0B三维模式也执行img2col展开，但写入L0B时硬件自动转置，主接口中的<code>transpose</code>参数不改变该行为。调用前分别通过以下接口配置右矩阵对应的寄存器组：</p><ul><li><a href="../cube_datamove/cube_load_aux_config/asc_set_l13d_fmatrix_b.html">asc_set_l13d_fmatrix_b</a>：Feature Map属性。</li><li><a href="../cube_datamove/cube_load_aux_config/asc_set_l12l0b_3d_padding.html">asc_set_l12l0b_3d_padding</a>：Padding值与模式。</li><li><a href="../cube_datamove/cube_load_aux_config/asc_set_l13d_rpt_b.html">asc_set_l13d_rpt_b</a>：目的步长和Repeat参数。</li></ul><p>L0A和L0B三维接口也可用于普通二维矩阵装载，但地址、传输范围和配置寄存器仍应按三维接口规则计算。</p><h2 id="L1到L0B二维分形转置搬运">L1到L0B二维分形转置搬运<a class="header-anchor" href="#L1到L0B二维分形转置搬运">​</a></h2><p><a href="../cube_datamove/cube_compute_load/asc_copy_l12l0b_trans_arch_3510.html">asc_copy_l12l0b_trans</a>按<code>repeat</code>次数处理一个或多个512字节分形，并通过<code>src_stride</code>、<code>dst_gap</code>、<code>src_frac_gap</code>和<code>dst_frac_gap</code>控制Repeat之间及同一Repeat内的分形排布。</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_l12l0b_trans</span><span class="p">(</span><span class="n">__cb__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                             </span><span class="n">__cbuf__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                             </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">index_id</span><span class="p">,</span>
<span class="w">                                             </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">repeat</span><span class="p">,</span>
<span class="w">                                             </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">src_stride</span><span class="p">,</span>
<span class="w">                                             </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">dst_gap</span><span class="p">,</span>
<span class="w">                                             </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">dst_frac_gap</span><span class="p">,</span>
<span class="w">                                             </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">src_frac_gap</span><span class="p">)</span>
</code></pre></div><ul><li><code>src</code>需要32字节对齐，<code>dst</code>需要512字节对齐。</li><li>所有步长和间隔参数均以512字节分形为单位；<code>dst_gap</code>、<code>dst_frac_gap</code>和<code>src_frac_gap</code>的硬件生效步长为传入值加1。</li><li><code>index_id</code>指定源矩阵的起始分形序号；每次Repeat处理的分形个数和方块矩阵形状随数据位宽变化，应按接口文档为对应数据类型计算。</li><li>目的分形不能发生重叠，<code>repeat</code>为0时不执行搬运。</li></ul><h2 id="MX量化系数搬运">MX量化系数搬运<a class="header-anchor" href="#MX量化系数搬运">​</a></h2><p>MX矩阵计算需要把主矩阵和对应量化系数分别装载到L0A/L0A_MX或L0B/L0B_MX。量化系数搬运接口包括：</p><ul><li><a href="../cube_datamove/cube_compute_load/asc_copy_l12l0a_mx.html">asc_copy_l12l0a_mx</a>：量化系数分形固定为16×2，对应L0A中一个16×32数据分形的地址映射。</li><li><a href="../cube_datamove/cube_compute_load/asc_copy_l12l0b_mx.html">asc_copy_l12l0b_mx</a>：量化系数分形固定为2×16，对应L0B中一个32×16数据分形的地址映射。</li></ul><p>两个接口的源L1和目的MX Buffer地址均需要32字节对齐，最小搬运粒度为一个32字节量化系数分形。L0A_MX和L0B_MX容量各为4KB。<code>x_step</code>或<code>y_step</code>为0时接口为空操作；目的地址和步长必须与主矩阵分形建立正确映射。</p><h2 id="asc_copy_l0c2l1（L0C到L1随路处理搬运）">asc_copy_l0c2l1（L0C到L1随路处理搬运）<a class="header-anchor" href="#asc_copy_l0c2l1（L0C到L1随路处理搬运）">​</a></h2><p>该接口从L0C搬出<code>int32_t</code>或<code>float</code>矩阵结果，在写入L1时可组合类型转换、scalar/tensor量化、ReLU或Leaky ReLU、Nz2ND/Nz2DN、通道拆分和UnitFlag。</p><p>启用相应能力前，通过以下接口配置状态：</p><table><thead><tr><th>功能</th><th>配置接口</th></tr></thead><tbody><tr><td>Nz2ND/Nz2DN</td><td><a href="../cube_datamove/cube_store_aux_config/asc_set_l0c_copy_nz_para.html">asc_set_l0c_copy_nz_para</a></td></tr><tr><td>Nz2DN通道参数</td><td><a href="../cube_datamove/cube_store_aux_config/asc_set_l0c_copy_channel_para.html">asc_set_l0c_copy_channel_para</a></td></tr><tr><td>scalar量化</td><td><a href="../cube_datamove/cube_store_aux_config/asc_set_l0c_copy_prequant.html">asc_set_l0c_copy_prequant</a></td></tr><tr><td>tensor量化参数地址</td><td><a href="../cube_datamove/cube_store_aux_config/asc_set_l0c_copy_config.html">asc_set_l0c_copy_config</a></td></tr><tr><td>ReLU/Leaky ReLU参数</td><td><a href="../cube_datamove/cube_store_aux_config/asc_set_l0c_copy_relu_alpha.html">asc_set_l0c_copy_relu_alpha</a>、<a href="../cube_datamove/cube_store_aux_config/asc_set_l0c_copy_lrelu_alpha.html">asc_set_l0c_copy_lrelu_alpha</a></td></tr></tbody></table><p><code>src</code>需要64字节对齐，<code>dst</code>需要32字节对齐。<code>n_size</code>、<code>m_size</code>和<code>dst_stride</code>的对齐由目的数据位宽及输出格式共同决定，源、目的数据类型必须与<code>quant_pre_mode</code>匹配。</p><h2 id="同步与边界检查">同步与边界检查<a class="header-anchor" href="#同步与边界检查">​</a></h2><ul><li>L1由PIPE_MTE2或其他流水写入后，PIPE_MTE1读取前需要建立依赖；L0A/L0B写入后，PIPE_M发起矩阵计算前也需要建立依赖。</li><li>PIPE_M写入L0C后，PIPE_FIX搬出结果前需要同步，或在满足接口约束时使用UnitFlag建立分形粒度的并行。</li><li>L1容量上限为512KB，L0A/L0B各64KB，L0C为256KB；二维和三维模式均需把完整边界分形计入访问范围。</li><li>配置接口设置的Feature Map、Padding、Repeat、量化和格式转换状态会影响后续搬运，复用前应按当前任务重新核对。</li></ul></article></div>`,1)])])}const u=s(_,[["render",l]]);export{h as __pageData,u as default};
